<?php
declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';
require_admin();
$table='subscribers';$title='Subscribers';$desc='Newsletter subscribers';
$id=(int)get('id',0);$action=(string)get('action','list');$cols=columns($table);$names=array_column($cols,'Field');$editable=array_values(array_filter($names,fn($n)=>!in_array($n,['id','created_at','updated_at','deleted_at'])));
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$op=(string)post('op');if($op==='delete'&&$id){dbq("DELETE FROM `".safe_table($table)."` WHERE id=?",[$id]);flash('success','Record deleted.');redirect(url(basename(__FILE__,'.php')));}if($op==='save'){ $data=[];foreach($editable as $c){if(in_array($c,['password','token','remember_token','verification_code','sms_code','transpin']))continue;$v=post($c,null);if($v!==null)$data[$c]=is_array($v)?json_encode($v):$v;}if($table==='users'&&isset($_POST['password'])&&$_POST['password']!=='')$data['password']=password_hash((string)$_POST['password'],PASSWORD_DEFAULT);if($id){$sets=[];$vals=[];foreach($data as $c=>$v){$sets[]="`$c`=?";$vals[]=$v;}$vals[]=$id;if($sets)dbq("UPDATE `".safe_table($table)."` SET ".implode(',',$sets)." WHERE id=?",$vals);}else{if(in_array('created_at',$names))$data['created_at']=date('Y-m-d H:i:s');$cs=array_keys($data);$ph=implode(',',array_fill(0,count($cs),'?'));if($cs)dbq("INSERT INTO `".safe_table($table)."` (`".implode('`,`',$cs)."`) VALUES ($ph)",array_values($data));}flash('success','Record saved.');log_action('crud_save',$title);redirect(url(basename(__FILE__,'.php')));}}
$rows=[];if($action==='edit'&&$id)$row=dbone("SELECT * FROM `".safe_table($table)."` WHERE id=?",[$id]);$search=trim((string)get('q',''));$sql="SELECT * FROM `".safe_table($table)."`";$params=[];if($search){$usable=array_slice($editable,0,5);if($usable){$parts=[];foreach($usable as $c){$parts[]="CAST(`$c` AS CHAR) LIKE ?";$params[]='%'.$search.'%';}$sql.=' WHERE '.implode(' OR ',$parts);}}$sql.=' ORDER BY id DESC LIMIT 100';try{$rows=dball($sql,$params);}catch(Throwable $e){$rows=[];$loadError=$e->getMessage();}
$title=$title;require __DIR__.'/includes/header.php';?>
<div class="section-head"><div><h1><?=e($title)?></h1><div class="muted"><?=e($desc)?></div></div><a class="btn" href="<?=e(url(basename(__FILE__,'.php'),['action'=>'edit']))?>">Add new</a></div>
<?php if(isset($loadError)):?><div class="alert danger">Database error: <?=e($loadError)?></div><?php endif;?>
<div class="card"><form method="get" class="actions"><input type="hidden" name="page" value="<?=e(basename(__FILE__,'.php'))?>"><input name="q" placeholder="Search records" value="<?=e($search)?>"><button class="btn btn-secondary">Search</button></form></div><br>
<?php if($action==='edit'):?><div class="card"><h3><?=e($id?'Edit':'Create')?> <?=e($title)?></h3><form method="post"><?=csrf_field()?><input type="hidden" name="op" value="save"><div class="form-grid">
<?php foreach($editable as $c): if(in_array($c,['token','remember_token','verification_code','sms_code','transpin','deleted_at']))continue; $v=$row[$c]??''; $type=str_contains($c,'password')?'password':(str_contains($c,'email')?'email':'text'); ?><div class="field"><label><?=e(ucwords(str_replace('_',' ',$c)))?></label><?php if(in_array($c,['details','description','info','about','terms','privacy','policy'])):?><textarea name="<?=e($c)?>"><?=e($v)?></textarea><?php else:?><input type="<?=$type?>" name="<?=e($c)?>" value="<?=e($type==='password'?'':$v)?>"><?php endif;?></div><?php endforeach;?></div><br><button class="btn">Save</button> <a class="btn btn-secondary" href="<?=e(url(basename(__FILE__,'.php')))?>">Cancel</a></form></div>
<?php else:?><div class="table-wrap"><table class="table"><thead><tr><?php foreach($editable as $c):?><th><?=e(ucwords(str_replace('_',' ',$c)))?></th><?php endforeach;?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($editable as $c):?><td><?=e(value_for($r,$c))?></td><?php endforeach;?><td class="actions"><a class="btn btn-sm btn-secondary" href="<?=e(url(basename(__FILE__,'.php'),['action'=>'edit','id'=>$r['id']]))?>">Edit</a><form method="post" onsubmit="return confirm('Delete this record?')" style="display:inline"><?=csrf_field()?><input type="hidden" name="op" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<?php require __DIR__.'/includes/footer.php';?>
